using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.Quizzes;
[Authorize(Roles="Admin")] public class EditModel:PageModel{private readonly ApplicationDbContext _db;private readonly ImageStorageService _images;public EditModel(ApplicationDbContext db,ImageStorageService images){_db=db;_images=images;}[BindProperty]public QuizInput Input{get;set;}=new();public int QuizId{get;private set;}public string? CurrentImageUrl{get;private set;}public class QuizInput{[Required,StringLength(100)]public string Title{get;set;}="";[StringLength(500)]public string Description{get;set;}="";public QuizType Type{get;set;}public int LessonId{get;set;}public bool IsActive{get;set;}public IFormFile? Image{get;set;}public bool RemoveImage{get;set;}}
public async Task<IActionResult> OnGetAsync(int id){var q=await _db.Quizzes.FindAsync(id);if(q is null)return NotFound();Set(q);await LoadLessonsAsync();return Page();}public async Task<IActionResult> OnPostAsync(int id){var q=await _db.Quizzes.FindAsync(id);if(q is null)return NotFound();QuizId=id;CurrentImageUrl=q.ImageUrl;if(!await _db.Lessons.AnyAsync(l=>l.Id==Input.LessonId&&l.Course.IsActive))ModelState.AddModelError("Input.LessonId","Select a lesson from an active course.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid){await LoadLessonsAsync();return Page();}q.Title=Input.Title.Trim();q.Description=Input.Description.Trim();q.Type=Input.Type;q.LessonId=Input.LessonId;q.IsActive=Input.IsActive;q.ImageUrl=await _images.ApplyAsync(q.ImageUrl,Input.Image,Input.RemoveImage,null);await _db.SaveChangesAsync();TempData["StatusMessage"]="Quiz updated.";return RedirectToPage("./Index");}private void Set(Quiz q){QuizId=q.Id;CurrentImageUrl=q.ImageUrl;Input=new(){Title=q.Title,Description=q.Description,Type=q.Type,LessonId=q.LessonId,IsActive=q.IsActive};}private async Task LoadLessonsAsync()=>ViewData["LessonId"]=new SelectList(await _db.Lessons.Include(l=>l.Course).Where(l=>l.Course.IsActive).OrderBy(l=>l.Course.Title).ThenBy(l=>l.OrderIndex).Select(l=>new{l.Id,Label=l.Course.Title+" — "+l.OrderIndex+". "+l.Title}).ToListAsync(),"Id","Label",Input.LessonId);}
